css:
.leadsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #25303b;
    background: linear-gradient(180deg, #f4f1ea 0%, #ece6da 100%);
    border-radius: 18px;
}

.leadsim-container * {
    box-sizing: border-box;
}

.leadsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #2b3a4a 0%, #1f2b38 60%, #16202b 100%);
    color: #f3f6f9;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #2f4254;
    box-shadow: 0 12px 30px rgba(22, 32, 43, 0.30);
}

.leadsim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.leadsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #f6a623;
    background: rgba(246, 166, 35, 0.14);
    border: 1px solid rgba(246, 166, 35, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.leadsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #c3d0dc;
}

.leadsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #4a5b6c;
    margin-bottom: 16px;
    padding: 6px 4px;
}

.leadsim-period-counter #currentDay,
.leadsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #c4641a;
}

.leadsim-round-name {
    background: rgba(196, 100, 26, 0.12);
    color: #c4641a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.leadsim-clock {
    margin-left: auto;
    font-size: 0.8rem;
    font-weight: 700;
    color: #9a3b1f;
    background: rgba(214, 78, 41, 0.10);
    border: 1px solid rgba(214, 78, 41, 0.28);
    padding: 4px 12px;
    border-radius: 999px;
}

.leadsim-dispatch-banner {
    text-align: center;
    background: linear-gradient(135deg, #f6a623 0%, #e8821a 100%);
    border-radius: 16px;
    padding: 18px 20px 16px;
    margin-bottom: 16px;
    border: 1px solid #d4751a;
    box-shadow: 0 8px 22px rgba(232, 130, 26, 0.32);
}

.leadsim-dispatch-label {
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 800;
    color: #5a2e08;
}

.leadsim-dispatch-value {
    font-size: 3.4rem;
    font-weight: 900;
    line-height: 1.05;
    margin: 2px 0;
    color: #2a1604;
    font-variant-numeric: tabular-nums;
    text-shadow: 0 1px 0 rgba(255, 255, 255, 0.35);
}

.leadsim-dispatch-sub {
    font-size: 0.82rem;
    font-weight: 600;
    color: #6b3a10;
}

.leadsim-dispatch-danger {
    background: linear-gradient(135deg, #d64e29 0%, #b23519 100%);
    border-color: #9a2e15;
}

.leadsim-dispatch-danger .leadsim-dispatch-label,
.leadsim-dispatch-danger .leadsim-dispatch-sub { color: #fbe3da; }
.leadsim-dispatch-danger .leadsim-dispatch-value { color: #fff4ef; text-shadow: none; }

.leadsim-dispatch-target {
    background: linear-gradient(135deg, #3aa66a 0%, #2c8854 100%);
    border-color: #246e44;
}

.leadsim-dispatch-target .leadsim-dispatch-label,
.leadsim-dispatch-target .leadsim-dispatch-sub { color: #e3f6ea; }
.leadsim-dispatch-target .leadsim-dispatch-value { color: #ffffff; text-shadow: none; }

.leadsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.leadsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #ddd5c7;
    box-shadow: 0 4px 14px rgba(43, 58, 74, 0.08);
    border-top: 4px solid #8a99a8;
}

.leadsim-card-coop { border-top-color: #2c8854; }
.leadsim-card-fair { border-top-color: #2e6fb0; }
.leadsim-card-adopt { border-top-color: #7a5cc4; }
.leadsim-card-turn { border-top-color: #d64e29; }

.leadsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6c7a89;
}

.leadsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #25303b;
    font-variant-numeric: tabular-nums;
}

.leadsim-card-coop .leadsim-value { color: #2c8854; }
.leadsim-card-fair .leadsim-value { color: #2e6fb0; }
.leadsim-card-adopt .leadsim-value { color: #7a5cc4; }
.leadsim-card-turn .leadsim-value { color: #d64e29; }

.leadsim-sublabel {
    font-size: 0.76rem;
    color: #7e8a96;
    line-height: 1.35;
}

.leadsim-card-coop.leadsim-good .leadsim-value,
.leadsim-card-fair.leadsim-good .leadsim-value,
.leadsim-card-adopt.leadsim-good .leadsim-value { color: #2c8854; }
.leadsim-card-coop.leadsim-bad .leadsim-value,
.leadsim-card-fair.leadsim-bad .leadsim-value,
.leadsim-card-adopt.leadsim-bad .leadsim-value { color: #d64e29; }

.leadsim-card-turn.leadsim-turn-high { border-top-color: #b23519; }
.leadsim-card-turn.leadsim-turn-high .leadsim-value { color: #b23519; }
.leadsim-card-turn.leadsim-turn-low { border-top-color: #2c8854; }
.leadsim-card-turn.leadsim-turn-low .leadsim-value { color: #2c8854; }

.leadsim-gap-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fff;
    border: 1px solid #ddd5c7;
    border-left: 5px solid #2e6fb0;
    color: #3a4856;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.9rem;
}

.leadsim-gap-bar #gapDisplay {
    font-size: 1.1rem;
    letter-spacing: 0.3px;
    color: #2e6fb0;
}

.leadsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #f6a623;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid #e3dccd;
    box-shadow: 0 4px 14px rgba(43, 58, 74, 0.07);
}

.leadsim-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.leadsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #25303b;
    margin-bottom: 6px;
}

.leadsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #45525f;
}

.leadsim-briefing-text strong { color: #c4641a; }
.leadsim-briefing-text em { color: #2e6fb0; font-style: italic; }

.leadsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e3dccd;
    box-shadow: 0 4px 14px rgba(43, 58, 74, 0.07);
}

.leadsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #25303b;
    border-bottom: 2px solid #ece6da;
    padding-bottom: 8px;
}

.leadsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #34414e;
    margin: 14px 0 6px;
}

.leadsim-container select,
.leadsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c9d0d8;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbfaf6;
    color: #25303b;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.leadsim-container select:focus,
.leadsim-container input[type="number"]:focus {
    outline: none;
    border-color: #f6a623;
    box-shadow: 0 0 0 3px rgba(246, 166, 35, 0.20);
}

.leadsim-container select option {
    background-color: #fbfaf6;
    color: #25303b;
}

.leadsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #f6a623;
}

.leadsim-range-readout,
.leadsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #4a5b6c;
    margin-top: 4px;
}

.leadsim-range-readout span:last-child,
.leadsim-alloc-readout span:nth-child(2) {
    color: #c4641a;
    font-weight: 800;
}

.leadsim-hint {
    font-size: 0.8rem;
    color: #7e8a96;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.leadsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.leadsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f7f4ee;
    border: 1px solid #e0d9cb;
    border-radius: 9px;
    padding: 9px 12px;
}

.leadsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #3a4856;
}

.leadsim-alloc-row input[type="number"] {
    width: 80px;
    flex: 0 0 80px;
    text-align: center;
    font-weight: 700;
}

.leadsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.leadsim-container .btn-primary {
    background: linear-gradient(135deg, #e8821a 0%, #f6a623 100%);
    border: none;
    color: #2a1604;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(232, 130, 26, 0.35);
}

.leadsim-container .btn-primary:hover {
    filter: brightness(1.05);
}

.leadsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c9d0d8;
    color: #6c7a89;
    background: transparent;
}

.leadsim-coach {
    background: linear-gradient(135deg, #2b3a4a 0%, #1f2b38 100%);
    color: #d8e2ec;
    border: 1px solid #2f4254;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(22, 32, 43, 0.22);
}

.leadsim-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f6a623;
    margin-bottom: 8px;
}

.leadsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.leadsim-coach-body strong { color: #f6a623; }
.leadsim-coach-body em { color: #7fb4ec; font-style: italic; }

.leadsim-history,
.leadsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e3dccd;
    box-shadow: 0 4px 14px rgba(43, 58, 74, 0.07);
}

.leadsim-history h3,
.leadsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #25303b;
}

.leadsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a4856;
}

.leadsim-container table#usfHistoryTable th {
    background: #f4f1ea;
    color: #c4641a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e0d9cb;
}

.leadsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #ece6da;
    color: #45525f;
}

.leadsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf8f2;
}

.leadsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .leadsim-container {
        padding: 14px;
    }
    .leadsim-header h1 {
        font-size: 1.7rem;
    }
    .leadsim-dispatch-value {
        font-size: 2.6rem;
    }
    .leadsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .leadsim-value {
        font-size: 2rem;
    }
    .leadsim-clock {
        margin-left: 0;
    }
    .leadsim-period-counter {
        font-size: 0.88rem;
    }
    .leadsim-gap-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .leadsim-alloc-row {
        flex-wrap: wrap;
    }
    .leadsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .leadsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion-message card (appended; dark-on-light, self-contained) */
.leadsim-cm { background:#f7f8fb; color:#141a24; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(0,0,0,0.18); }
.leadsim-cm-head { text-align:center; border-bottom:1px solid #dde2ea; padding-bottom:14px; margin-bottom:16px; }
.leadsim-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#5b6673; font-weight:700; }
.leadsim-cm-scorewrap { margin:8px 0 2px; }
.leadsim-cm-score { font-size:52px; font-weight:800; color:#2f6bd6; line-height:1; }
.leadsim-cm-score-max { font-size:20px; color:#889;  font-weight:600; }
.leadsim-cm-grade { font-size:19px; font-weight:700; color:#141a24; margin-top:4px; }
.leadsim-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.leadsim-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.leadsim-cm-met { background:#d6e2fa; color:#264f9e; }
.leadsim-cm-fail { background:#fce0dc; color:#a4322a; }
.leadsim-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.leadsim-cm-metric { background:#eceff5; border-radius:10px; padding:12px 16px; min-width:104px; text-align:center; }
.leadsim-cm-metric-val { font-size:22px; font-weight:800; color:#141a24; }
.leadsim-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#5b6673; margin-top:3px; }
.leadsim-cm-insights { background:#eceff5; border-radius:10px; padding:14px 18px; }
.leadsim-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#5b6673; font-weight:700; margin-bottom:8px; }
.leadsim-cm-insights ul { margin:0; padding-left:18px; }
.leadsim-cm-insights li { font-size:14px; line-height:1.5; color:#2c333f; margin-bottom:7px; }

