(function() {
    'use strict';

    class LeadByExampleAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Lead by Example`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Lyon mega-hub, Vélocité × Septentrion).
            this.DISPATCH_START = 81;     // % on-time dispatch in first 72h (down from 96%)
            this.DISPATCH_TARGET = 95;    // % client commitment within 6 weeks
            this.DISPATCH_EXIT = 90;      // % exit-clause trigger if sub-90 through peak
            this.FAIR_VELO = 38;          // perceived fairness, legacy Vélocité (south)
            this.FAIR_SEPT = 61;          // perceived fairness, legacy Septentrion (north)
            this.HEADCOUNT = 600;         // merged hub headcount (360 + 240)
            this.ROLES_CUT = 70;          // roles to remove (~12%) within 90 days
            this.TURNOVER_START = 18;     // % 6-month exit intent
            this.DRIVER_REPLACE = 14;     // ~EUR 14k to replace a trained driver
            this.SIGNAL_BUDGET = 10;      // high-visibility fairness signals to allocate

            // Concept truths (the modelled, exemplary, justice-first path).
            this.TRUE_DIAG = `justice`;
            this.TRUE_SIGNAL = `early`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    dispatch: this.DISPATCH_START,                              // % on-time dispatch
                    coop: 42,                                                   // cooperation index (0–100)
                    fair: Math.round((this.FAIR_VELO * 360 + this.FAIR_SEPT * 240) / 600), // blended fairness ≈ 47
                    fairVelo: this.FAIR_VELO,
                    fairSept: this.FAIR_SEPT,
                    adopt: 35,                                                  // change adoption (0–100)
                    turnover: this.TURNOVER_START,                             // % exit intent (lower better)
                    diagnosedJustice: false,                                    // named the real root cause in R1
                    exemplary: false,                                          // modelled exemplary behaviour in R3
                    favouredLegacy: false,                                     // visibly favoured one legacy
                    rushedCuts: false,                                         // executed cuts fast, skipped voice
                    dispatchHistory: [this.DISPATCH_START],
                    coopHistory: [42],
                    fairHistory: [Math.round((this.FAIR_VELO * 360 + this.FAIR_SEPT * 240) / 600)],
                    adoptHistory: [35],
                    turnoverHistory: [this.TURNOVER_START],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the CLASSIC ERRORS — a click-through must not auto-win.
                state.decisions = {
                    diag: `hands`,
                    signal: `rumor`,
                    model: 50,
                    comm: `silence`,
                    leadership: 2, roster: 2, training: 2, consistency: 2, perks: 2,
                    process: `closed`,
                    modelBehavior: `delegate`,
                    even: `protect`,
                    injection: `ignore`,
                    scorecard: `dispatch`,
                    norm: `incentives`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const dg = document.getElementById(`diagInput`);
                const sg = document.getElementById(`signalInput`);
                const md = document.getElementById(`modelInput`);
                if (dg) decisions.diag = dg.value;
                if (sg) decisions.signal = sg.value;
                if (md) decisions.model = parseInt(md.value, 10);
                if (!Number.isFinite(decisions.model) || decisions.model < 0 || decisions.model > 100) {
                    warn(`warn_model_range`); return false;
                }
            } else if (round === 2) {
                const cm = document.getElementById(`commInput`);
                if (cm) decisions.comm = cm.value;
                const ids = [`leadershipInput`, `rosterInput`, `trainingInput`, `consistencyInput`, `perksInput`];
                const keys = [`leadership`, `roster`, `training`, `consistency`, `perks`];
                for (let i = 0; i < ids.length; i++) {
                    const el = document.getElementById(ids[i]);
                    if (el) decisions[keys[i]] = parseInt(el.value, 10);
                }
                const vals = keys.map((k) => decisions[k]);
                if (vals.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = vals.reduce((a, b) => a + b, 0);
                if (total !== this.SIGNAL_BUDGET) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 3) {
                const pr = document.getElementById(`processInput`);
                const mb = document.getElementById(`modelBehaviorInput`);
                const ev = document.getElementById(`evenInput`);
                const ij = document.getElementById(`injectionInput`);
                if (pr) decisions.process = pr.value;
                if (mb) decisions.modelBehavior = mb.value;
                if (ev) decisions.even = ev.value;
                if (ij) decisions.injection = ij.value;
                if (!decisions.process || !decisions.modelBehavior || !decisions.even || !decisions.injection) {
                    warn(`warn_r3_incomplete`); return false;
                }
            } else if (round === 4) {
                const sc = document.getElementById(`scorecardInput`);
                const nm = document.getElementById(`normInput`);
                const cv = document.getElementById(`convictionInput`);
                if (sc) decisions.scorecard = sc.value;
                if (nm) decisions.norm = nm.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas: coop, fair (blended), adopt (0–100), turnover (% — POSITIVE delta = worse),
            // dispatch (% — driven by cooperation recovery, not by adding hands).
            let coopDelta = 0, fairDelta = 0, adoptDelta = 0, turnDelta = 0;
            let veloDelta = 0, septDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // R1 — Diagnose: symptom (dispatch) vs root cause (justice & cooperation).
                switch (d.diag) {
                    case `justice`:
                        ds.diagnosedJustice = true;
                        coopDelta += 6; fairDelta += 4; adoptDelta += 4; coachKey = `coach_r1_justice`; break;
                    case `hands`:
                        // Common Error 1 — operations-only response.
                        coopDelta -= 4; fairDelta -= 2; coachKey = `coach_r1_hands`; break;
                    case `it`:
                        adoptDelta -= 2; coachKey = `coach_r1_it`; break;
                    case `north`:
                        // Common Error 5 — favouring one legacy at the diagnosis stage.
                        ds.favouredLegacy = true;
                        veloDelta -= 8; septDelta += 1; coopDelta -= 5; coachKey = `coach_r1_north`; break;
                }

                // Which fairness signal is misfiring — naming the manager's own early signals is the insight.
                switch (d.signal) {
                    case `early`: fairDelta += 5; coopDelta += 3; if (ds.diagnosedJustice) coachKey = `coach_r1_sharp`; break;
                    case `pay`: fairDelta += 1; break;
                    case `rumor`: fairDelta -= 1; break;
                    case `none`: fairDelta -= 4; coopDelta -= 3; coachKey = `coach_r1_signalnone`; break;
                }

                // Commitment to model even-handedness first (exemplarity primer).
                if (d.model >= 60) { fairDelta += 4; coopDelta += 3; }
                else if (d.model <= 25) { fairDelta -= 3; coopDelta -= 2; coachKey = `coach_r1_lowmodel`; }

                summaryKey = (d.diag === `justice` && d.signal === `early`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // R2 — Communication + fairness-signal allocation.
                // (a) Communication as a fairness signal (Common Error 2 — strategic silence).
                switch (d.comm) {
                    case `honest`: fairDelta += 8; coopDelta += 6; adoptDelta += 6; turnDelta -= 3; coachKey = `coach_r2_honest`; break;
                    case `memo`: fairDelta += 1; adoptDelta += 1; coachKey = `coach_r2_memo`; break;
                    case `silence`:
                        fairDelta -= 8; coopDelta -= 4; turnDelta += 4; coachKey = `coach_r2_silence`; break;
                }

                // (b) Allocation of the 10 fairness signals (procedural / interactional weighting).
                const procedural = d.leadership + d.roster;          // balanced leadership + jointly designed roster
                const distributive = d.training;                     // equal IT training access
                const interactional = d.consistency;                 // consistency between ask & action (exemplarity)
                const perks = d.perks;                               // visible status spend = anti-signal

                // Procedural & interactional justice carry more weight than distributive (Melkonian).
                fairDelta += procedural * 2.0 + interactional * 2.6 + distributive * 1.0 - perks * 2.4;
                coopDelta += procedural * 1.6 + interactional * 1.8 - perks * 1.4;
                adoptDelta += d.roster * 1.4 + distributive * 1.6 + interactional * 0.8;
                // A jointly designed roster narrows the legacy gap directly (voice for the south).
                veloDelta += d.roster * 1.5 + d.leadership * 1.2 + interactional * 1.0 - perks * 1.0;
                septDelta += d.leadership * 0.4;

                if (perks >= 4) {
                    // Inconsistent exemplarity already showing (Common Error 4).
                    coachKey = `coach_r2_perks`;
                } else if (interactional >= 3 && procedural >= 4 && d.comm === `honest`) {
                    coachKey = `coach_r2_balanced`;
                }

                summaryKey = (d.comm === `honest` && perks <= 1 && interactional >= 2) ? `sum_r2_good` :
                             (d.comm === `silence` ? `sum_r2_silence` : `sum_r2_weak`);
            } else if (round === 3) {
                // R3 — Execute the redundancy + model behaviour under fire.
                // Process design (Common Error 3 — outcome over process; Common Error 6 — speed over fairness).
                switch (d.process) {
                    case `fair`: fairDelta += 10; coopDelta += 6; adoptDelta += 5; turnDelta -= 3; coachKey = `coach_r3_fair`; break;
                    case `closed`: fairDelta += 1; coopDelta -= 4; turnDelta += 3; coachKey = `coach_r3_closed`; break;
                    case `fast`:
                        ds.rushedCuts = true;
                        fairDelta -= 8; coopDelta -= 7; adoptDelta -= 4; turnDelta += 6; coachKey = `coach_r3_fast`; break;
                }

                // Modelled behaviour (exemplarity — the loudest, cheapest signal).
                switch (d.modelBehavior) {
                    case `exemplary`:
                        ds.exemplary = true;
                        fairDelta += 8; coopDelta += 7; adoptDelta += 4; turnDelta -= 3; break;
                    case `mixed`: fairDelta += 2; coopDelta += 1; break;
                    case `delegate`:
                        // Inconsistent exemplarity (Common Error 4).
                        fairDelta -= 7; coopDelta -= 5; turnDelta += 3; coachKey = `coach_r3_delegate`; break;
                }

                // Even-handedness across legacies (Common Error 5 — favouring one legacy).
                switch (d.even) {
                    case `even`: veloDelta += 7; fairDelta += 4; coopDelta += 3; break;
                    case `drift`: veloDelta -= 4; coopDelta -= 2; break;
                    case `protect`:
                        ds.favouredLegacy = true;
                        veloDelta -= 9; coopDelta -= 5; turnDelta += 3; coachKey = `coach_r3_protect`; break;
                }

                // The mid-round injection: rumour the cuts fall on the south + walkout + star resignation.
                switch (d.injection) {
                    case `address`: fairDelta += 6; coopDelta += 6; veloDelta += 5; turnDelta -= 4; coachKey = `coach_r3_address`; break;
                    case `suppress`: fairDelta -= 4; coopDelta -= 3; turnDelta += 3; coachKey = `coach_r3_suppress`; break;
                    case `ignore`: fairDelta -= 6; coopDelta -= 5; turnDelta += 5; veloDelta -= 4; coachKey = `coach_r3_inject_ignore`; break;
                }

                summaryKey = (d.process === `fair` && d.modelBehavior === `exemplary` && d.even === `even` && d.injection === `address`) ? `sum_r3_good` :
                             (ds.rushedCuts ? `sum_r3_rushed` : `sum_r3_weak`);
            } else if (round === 4) {
                // R4 — Recover cooperation & set the new norm; report against baseline.
                switch (d.scorecard) {
                    case `honest`: fairDelta += 6; coopDelta += 5; adoptDelta += 6; coachKey = `coach_r4_honest`; break;
                    case `dispatch`: adoptDelta -= 2; coopDelta -= 2; coachKey = `coach_r4_dispatch`; break;
                    case `spin`: fairDelta -= 5; coopDelta -= 3; turnDelta += 2; coachKey = `coach_r4_spin`; break;
                }

                // What sustains cooperation — norms & exemplarity vs incentives/surveillance.
                switch (d.norm) {
                    case `norms`: coopDelta += 8; adoptDelta += 8; fairDelta += 5; turnDelta -= 4; coachKey = `coach_r4_norms`; break;
                    case `incentives`: coopDelta += 2; turnDelta -= 1; coachKey = `coach_r4_incentives`; break;
                    case `monitor`: coopDelta -= 4; fairDelta -= 3; adoptDelta -= 2; coachKey = `coach_r4_monitor`; break;
                }

                // Conviction behind procedural fairness.
                if (d.conviction >= 60) { fairDelta += 4; coopDelta += 3; }
                else if (d.conviction <= 25) { fairDelta -= 4; coopDelta -= 3; }

                summaryKey = (d.scorecard === `honest` && d.norm === `norms`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply legacy-specific fairness movements, then recompute the blended fairness & gap.
            ds.fairVelo = Math.max(0, Math.min(100, Math.round(ds.fairVelo + fairDelta + veloDelta)));
            ds.fairSept = Math.max(0, Math.min(100, Math.round(ds.fairSept + fairDelta + septDelta)));
            ds.fair = Math.round((ds.fairVelo * 360 + ds.fairSept * 240) / 600);

            ds.coop = Math.max(0, Math.min(100, Math.round(ds.coop + coopDelta)));
            ds.adopt = Math.max(0, Math.min(100, Math.round(ds.adopt + adoptDelta)));
            ds.turnover = Math.max(0, Math.min(60, Math.round((ds.turnover + turnDelta) * 10) / 10));

            // Dispatch recovers as a FUNCTION OF COOPERATION, not of adding hands.
            // Cooperation above the day-one baseline (42) pulls dispatch toward the 95% target;
            // below it drags dispatch further down. This is the "can't supervise your way out" mechanic.
            const coopGap = ds.coop - 42;
            const dispatchTarget = this.DISPATCH_START + (this.DISPATCH_TARGET - this.DISPATCH_START) * (Math.max(0, ds.coop - 30) / 60);
            ds.dispatch = Math.max(70, Math.min(98, Math.round((ds.dispatch + (dispatchTarget - ds.dispatch) * 0.6 + coopGap * 0.08) * 10) / 10));

            ds.dispatchHistory.push(ds.dispatch);
            ds.coopHistory.push(ds.coop);
            ds.fairHistory.push(ds.fair);
            ds.adoptHistory.push(ds.adopt);
            ds.turnoverHistory.push(ds.turnover);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            // v1.1.0 fix: persist instructor-card composite to domainState every period.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                dispatch: ds.dispatch,
                coop: ds.coop,
                coopDelta: Math.round(coopDelta),
                fair: ds.fair,
                fairVelo: ds.fairVelo,
                fairSept: ds.fairSept,
                gap: ds.fairSept - ds.fairVelo,
                adopt: ds.adopt,
                turnover: ds.turnover,
                exemplary: ds.exemplary,
                favouredLegacy: ds.favouredLegacy,
                rushedCuts: ds.rushedCuts,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtPct(v) { return Math.round(Number(v)) + `%`; }

        _fmtTurn(v) {
            const n = Number(v);
            return (Math.round(n * 10) / 10) + `%`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`dispatchDisplay`, `domainState.dispatch`, (v) => {
                const b = document.querySelector(`.leadsim-dispatch-banner`);
                if (b) {
                    b.classList.toggle(`leadsim-dispatch-danger`, Number(v) < self.DISPATCH_EXIT);
                    b.classList.toggle(`leadsim-dispatch-target`, Number(v) >= self.DISPATCH_TARGET);
                }
                return self._fmtPct(v);
            });
            uiManager.bind(`coopDisplay`, `domainState.coop`, (v) => {
                self._tone(`.leadsim-card-coop`, Number(v), 60, 40);
                return Math.round(Number(v));
            });
            uiManager.bind(`fairDisplay`, `domainState.fair`, (v) => {
                self._tone(`.leadsim-card-fair`, Number(v), 60, 40);
                return Math.round(Number(v));
            });
            uiManager.bind(`adoptDisplay`, `domainState.adopt`, (v) => {
                self._tone(`.leadsim-card-adopt`, Number(v), 60, 40);
                return Math.round(Number(v));
            });
            uiManager.bind(`turnDisplay`, `domainState.turnover`, (v) => {
                const card = document.querySelector(`.leadsim-card-turn`);
                if (card) {
                    card.classList.toggle(`leadsim-turn-high`, Number(v) >= 18);
                    card.classList.toggle(`leadsim-turn-low`, Number(v) <= 10);
                }
                return self._fmtTurn(v);
            });
            uiManager.bind(`gapDisplay`, `domainState.fairSept`, (v) => {
                const ds = window.mySimulation.state.domainState;
                const gap = Math.max(0, Math.round(ds.fairSept - ds.fairVelo));
                return gap + ` ` + window.mySimulation.t(`pts`);
            });

            // Model-behaviour slider readout (R1).
            const md = document.getElementById(`modelInput`);
            const mdReadout = document.getElementById(`modelReadout`);
            if (md && mdReadout) {
                mdReadout.textContent = md.value;
                md.addEventListener(`input`, function() { mdReadout.textContent = md.value; });
            }

            // Fairness-signal allocation live total (must hit 10).
            const allocIds = [`leadershipInput`, `rosterInput`, `trainingInput`, `consistencyInput`, `perksInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseInt(el.value, 10) || 0);
                });
                if (allocReadout) allocReadout.textContent = total;
                const bar = document.querySelector(`.leadsim-alloc-readout`);
                if (bar) bar.style.color = (total !== self.SIGNAL_BUDGET) ? `#d64e29` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        _tone(sel, v, goodAt, badAt) {
            const card = document.querySelector(sel);
            if (!card) return;
            card.classList.toggle(`leadsim-good`, v >= goodAt);
            card.classList.toggle(`leadsim-bad`, v <= badAt);
        }

