        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.coopHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : window.mySimulation.t(`chart_round_prefix`) + i));
            return {
                leadChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.coopHistory },
                        { data: ds.fairHistory },
                        { data: ds.adoptHistory },
                        { data: ds.turnoverHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            const dispatch = Math.round(ds.dispatch);
            const coop = Math.round(ds.coop);
            const fair = Math.round(ds.fair);
            const adopt = Math.round(ds.adopt);
            const turnover = Math.round(ds.turnover * 10) / 10;
            const dispatchScore = Math.max(0, Math.min(100, (dispatch - 75) / (this.DISPATCH_TARGET - 75) * 100));
            const turnoverScore = Math.max(0, Math.min(100, (60 - turnover) / (60 - 6) * 100));
            return Math.round(coop * 0.26 + fair * 0.24 + adopt * 0.16 + turnoverScore * 0.16 + dispatchScore * 0.18);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const dispatch = Math.round(ds.dispatch);
            const coop = Math.round(ds.coop);
            const fair = Math.round(ds.fair);
            const adopt = Math.round(ds.adopt);
            const turnover = Math.round(ds.turnover * 10) / 10;
            const gap = Math.max(0, Math.round(ds.fairSept - ds.fairVelo));

            // Composite: cooperation, fairness, adoption, low turnover, and the dispatch recovery.
            const composite = this._composite(ds);

            const cooperating = coop >= 60 && fair >= 58;
            const dispatchHeld = dispatch >= this.DISPATCH_TARGET;
            const dispatchSafe = dispatch >= this.DISPATCH_EXIT;
            const talentHeld = turnover <= 10;
            const fairBalance = gap <= 10;
            const fractured = ds.favouredLegacy && gap >= 18;

            let performanceKey = `grade_fractured`;
            if (cooperating && dispatchHeld && talentHeld && fairBalance && composite >= 75) performanceKey = `grade_oneteam`;
            else if (cooperating && dispatchSafe) performanceKey = `grade_stabilised`;
            else if (fractured || (ds.rushedCuts && fair < 45)) performanceKey = `grade_justice`;
            else if (!dispatchSafe) performanceKey = `grade_contract`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const met = cooperating && dispatchHeld && talentHeld && fairBalance && composite >= 75;
            const contractLost = !dispatchSafe;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (cooperating && dispatchHeld && talentHeld) insights.push(window.mySimulation.t(`insight_oneteam`));
            else if (fractured) insights.push(window.mySimulation.t(`insight_fractured`));
            else insights.push(window.mySimulation.t(`insight_partial`));

            if (!dispatchSafe) insights.push(window.mySimulation.t(`insight_contract`));
            else if (dispatchHeld) insights.push(window.mySimulation.t(`insight_dispatch`));
            if (ds.rushedCuts) insights.push(window.mySimulation.t(`insight_rushed`));
            if (!ds.exemplary) insights.push(window.mySimulation.t(`insight_noexemplar`));
            if (turnover >= 18) insights.push(window.mySimulation.t(`insight_turnover`));
            if (fairBalance && cooperating) insights.push(window.mySimulation.t(`insight_balanced`));

            return {
                dispatch: dispatch,
                coop: coop,
                fair: fair,
                adopt: adopt,
                turnover: turnover,
                gap: gap,
                cooperating: cooperating,
                dispatchHeld: dispatchHeld,
                talentHeld: talentHeld,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                fractured: fractured,
                contractLost: contractLost,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="leadsim-cm-badge ` + (s.met ? `leadsim-cm-met` : `leadsim-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.fractured) badges.push(`<span class="leadsim-cm-badge leadsim-cm-fail">` + t(`cm_fail_justice`) + `</span>`);
            if (s.contractLost) badges.push(`<span class="leadsim-cm-badge leadsim-cm-fail">` + t(`cm_fail_contract`) + `</span>`);
            if (s.talentHeld === false) badges.push(`<span class="leadsim-cm-badge leadsim-cm-fail">` + t(`cm_fail_turnover`) + `</span>`);
            const kpi = (label, val) => `<div class="leadsim-cm-metric"><div class="leadsim-cm-metric-val">` + val + `</div><div class="leadsim-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_dispatch`), (s.dispatch != null ? s.dispatch : 0) + `%`) + kpi(t(`cm_coop`), (s.coop != null ? s.coop : 0)) + kpi(t(`cm_fair`), (s.fair != null ? s.fair : 0)) + kpi(t(`cm_turnover`), (s.turnover != null ? s.turnover : 0) + `%`);
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="leadsim-cm">`
                + `<div class="leadsim-cm-head"><div class="leadsim-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="leadsim-cm-scorewrap"><span class="leadsim-cm-score">` + score + `</span><span class="leadsim-cm-score-max">/100</span></div>`
                + `<div class="leadsim-cm-grade">` + grade + `</div>`
                + `<div class="leadsim-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="leadsim-cm-metrics">` + kpis + `</div>`
                + `<div class="leadsim-cm-insights"><div class="leadsim-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.dispatch < this.DISPATCH_EXIT && state.currentPeriod >= 2) return window.mySimulation.t(`hint_dispatch`);
            if (ds.favouredLegacy && (ds.fairSept - ds.fairVelo) >= 18) return window.mySimulation.t(`hint_favour`);
            if (ds.rushedCuts) return window.mySimulation.t(`hint_rushed`);
            if (!ds.exemplary && state.currentPeriod >= 3) return window.mySimulation.t(`hint_exemplar`);
            if (ds.turnover >= 20) return window.mySimulation.t(`hint_turnover`);
            if (ds.coop >= 60 && ds.fair >= 58 && ds.dispatch >= this.DISPATCH_TARGET) return window.mySimulation.t(`hint_strong`);
            return null;
        }

