                { key: `results.dispatch`, label: `Dispatch`, i18nKey: `col_dispatch`, formatter: (v) => self._fmtPct(v) },
                { key: `results.coop`, label: `Cooperation`, i18nKey: `col_coop`, formatter: (v) => Math.round(v) },
                { key: `results.fair`, label: `Fairness`, i18nKey: `col_fair`, formatter: (v) => Math.round(v) },
                { key: `results.turnover`, label: `Turnover`, i18nKey: `col_turn`, formatter: (v) => self._fmtTurn(v) }
            ];
        }

